% volumes = zeros(1,size(femodel.Mesh.Elements,2));
% for i= 1:size(femodel.Mesh.Elements,2)
%     volumes(i) = volume(femodel.Mesh,i)/volume(femodel.Mesh);
% end

totalVolume = volume(femodel.Mesh);
nElem = size(femodel.Mesh.Elements,2);
volumes = zeros(1,nElem);
for k = 1:nElem
    volumes(k) = volume(femodel.Mesh,k)/totalVolume;
end

weights= zeros(1,size(femodel.Mesh.Nodes,2));
for i= 1:size(femodel.Mesh.Nodes,2)
    weights(i)=sum(volumes(sum(femodel.Mesh.Elements==i)==1))/10;
end
m_i = volume(femodel.Mesh)*femodel.MaterialProperties.MaterialAssignments.MassDensity*1e3;

AttachmentDoF = rom.RetainedDoF;
CondensedDOF = true(3*size(femodel.Mesh.Nodes,2), 1);
CondensedDOF(AttachmentDoF) = false;
CondensedDoF = find(CondensedDOF);
DOF = [AttachmentDoF, CondensedDoF'];

Psi=TransformationMatrix(:,end);
% --- MAIN SCRIPT ---
z = [zeros(6,1); 0; zeros(6,1); 0];
% u_input = zeros(6,1);
u_input = [0; 0; 0; 1; 0; 0];
% 
% % Setup ODE options
% % 1. Pass the Mass matrix function (it must accept t and Z as arguments)
% % 2. Declare 'strong' state dependence so the solver computes the proper Jacobians
% opts = odeset('OutputFcn', @printProgress, ...
%               'Stats', 'on', ...
%               'Mass', @(t, Z) assembleMassMatrix_mex(femodel.Mesh.Nodes, origins, Psi, DOF, m_i, weights, Z), ...
%               'MStateDependence', 'strong');
% 
% % Solve the system using the updated RHS function
% [time, states] = ode15s(@(t,Z) cb_dynamics_rhs(t, Z, u_input, rom.K, femodel.Mesh.Nodes, origins, Psi, DOF, m_i, weights), [0, 1], z, opts);
% 
% % --- CORRECTED INDICES ---
% idx_pos       = 1:3;   % Translational position
% idx_quat      = 4:6;   % Euler( q1, q2, q3)
% idx_modal_pos = 7;     % Modal deflection (\delta)
% 
% idx_vel       = 8:10;  % Linear velocity
% idx_omega     = 11:13; % Angular velocity
% idx_modal_vel = 14;    % Modal velocity (\dot{\delta})

% --- LOCAL FUNCTIONS ---
function rhs = cb_dynamics_rhs(t, Z, u, K, nodes, origins, Psi, DOF, m_i, weights)
    % IMPORTANT: This function now ONLY returns the right-hand side.
    
    F_in = [eye(6,6); zeros(1,6)];
    gbar = [zeros(7,6); F_in];
    
    % Just return f(Z) + g*u
    rhs = computeForce(K,nodes, origins, Psi, DOF, m_i, weights, Z) + gbar * u;
end

function Q_aug = computeForce(K,nodes, origin_ref, Psi, DOF, m_i, weights, Z)
    n = 7;
    Q_c= computeCoriolisForce_mex(nodes, origin_ref, Psi, DOF, m_i, weights, Z);
    Q_st = [zeros(n-1,1);-K(end,end) * 1e3 * Z(2*n)];
    %% M ddotx = Qc+Q_e+Qg+Qst
    Q = Q_c+Q_st;
    % 1. Extract angles and angular velocity
    euler_rates = Z(11:13);
    % 4. Assemble the corrected state derivative vector
    % [ translation_vel; euler_rates; modal_vel; Accelerations ]
    Q_aug = [Z(8:10); euler_rates; Z(14); Q];
end

function femodel = createBeamModel(stlFile, material, origins)
    
    femodel = createpde('structural','modal-solid');
    importGeometry(femodel, stlFile);
    
    structuralProperties(femodel,...
        'YoungsModulus', material.E,...
        'PoissonsRatio', material.nu,...
        'MassDensity', material.rho);
    
    generateMesh(femodel,...
        'GeometricOrder','quadratic',...
        'Hmax',100,...
        'Hmin',100);
    
    structuralBC(femodel,...
        'Face',3,...
        'Constraint','multipoint',...
        'Reference',origins);

end
